def read_draft_raw(db_path, version):
    """只读核对既有 SQLite 数据格式：返回 (标题原文, 按 position 升序的变更原文列表)。

    用于交叉核对草稿原文、条目数量与顺序；不写库、不改变任何数据。
    """
    conn = sqlite3.connect(db_path)
    try:
        title_row = conn.execute(
            "SELECT title FROM drafts WHERE version = ?", (version,)
        ).fetchone()
        contents = [
            content
            for (content,) in conn.execute(
                "SELECT content FROM changes WHERE version = ?"
                " ORDER BY position",
                (version,),
            )
        ]
    finally:
        conn.close()
    return title_row[0], contents

